/*
 * [演算法說明]
 * 這是一個求「最大全 0 子矩陣面積」的問題。
 * 
 * 演算法步驟：
 * 1. 對於每一行，我們可以將其看作一個直方圖 (Histogram)。
 * 2. 直方圖中每個柱子的長度是從該行向上連續 0 的數量。
 * 3. 對於每一行產生的直方圖，使用「單調棧」(Monotonic Stack) 演算法求出該直方圖中的最大矩陣面積。
 * 4. 遍歷所有行，記錄最大的矩陣面積。
 * 
 * 時間複雜度：O(M * N)，其中 M 為行數，N 為列數。
 */

#include <iostream>
#include <vector>
#include <stack>
#include <algorithm>

using namespace std;

int largestRectangleArea(const vector<int>& heights) {
    stack<int> s;
    int max_area = 0;
    vector<int> h = heights;
    h.push_back(0); // 哨兵，確保最後清空棧

    for (int i = 0; i < h.size(); ++i) {
        while (!s.empty() && h[s.top()] >= h[i]) {
            int height = h[s.top()];
            s.pop();
            int width = s.empty() ? i : i - s.top() - 1;
            max_area = max(max_area, height * width);
        }
        s.push(i);
    }
    return max_area;
}

int main() {
    int M, N;
    while (cin >> M >> N && (M != 0 || N != 0)) {
        vector<vector<int>> grid(M, vector<int>(N));
        vector<int> heights(N, 0);
        int max_land = 0;

        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < N; ++j) {
                int val;
                cin >> val;
                if (val == 0) heights[j]++;
                else heights[j] = 0;
            }
            max_land = max(max_land, largestRectangleArea(heights));
        }
        cout << max_land << endl;
    }
    return 0;
}
